/**
 * Startup pane-record retirement requires independently proven child absence;
 * a failed placement capture is not such proof. This pure census turns one
 * webview-window enumeration into a per-pane verdict against the EXACT native
 * child label `pane-${pane}` (no title, ordinal, substring, or case folding).
 * Any malformation, duplicate exact label, or unusable entry fails closed to
 * "unknown", which callers must treat as "retain the popped record".
 */
export type PaneChildPresenceVerdict =
  | { kind: "absent" }
  | { kind: "present" }
  | { kind: "unknown"; reason: string };

export type PaneChildPresenceVerdictMap = Record<string, PaneChildPresenceVerdict>;

export const paneChildLabelForPane = (pane: string): string => `pane-${pane}`;

export const paneChildPresenceVerdicts = (
  panes: readonly string[],
  enumeratedWindows: unknown,
): PaneChildPresenceVerdictMap => {
  const verdicts: PaneChildPresenceVerdictMap = {};
  const unknownForAll = (reason: string) => {
    for (const pane of panes) verdicts[pane] = { kind: "unknown", reason };
  };
  if (!Array.isArray(enumeratedWindows)) {
    unknownForAll("window enumeration was not an array");
    return verdicts;
  }
  const exactLabelCounts = new Map<string, number>();
  let malformedReason: string | null = null;
  for (const candidate of enumeratedWindows) {
    const label = typeof candidate === "object" && candidate !== null
      ? (candidate as { label?: unknown }).label
      : undefined;
    if (typeof label !== "string" || label.length === 0) {
      malformedReason = malformedReason ?? "a listed window exposed no usable exact label";
      continue;
    }
    exactLabelCounts.set(label, (exactLabelCounts.get(label) ?? 0) + 1);
  }
  // One malformed entry means the census is incomplete, so absence is not
  // provable for any pane; presence reporting waits for a clean enumeration.
  if (malformedReason !== null) {
    unknownForAll(malformedReason);
    return verdicts;
  }
  for (const pane of panes) {
    const occurrences = exactLabelCounts.get(paneChildLabelForPane(pane)) ?? 0;
    verdicts[pane] = occurrences === 1
      ? { kind: "present" }
      : occurrences === 0
        ? { kind: "absent" }
        : { kind: "unknown", reason: `duplicate exact child label ${paneChildLabelForPane(pane)}` };
  }
  return verdicts;
};

const projectHistoryMutationFromUnknown = (value: unknown): ProjectHistoryMutationResult | null => {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Record<string, unknown>;
  if (candidate.history_status && candidate.authority) {
    return value as ProjectHistoryMutationResult;
  }
  if (candidate.mutation) return projectHistoryMutationFromUnknown(candidate.mutation);
  if (candidate.terminal) return projectHistoryMutationFromUnknown(candidate.terminal);
  if (candidate.result) return projectHistoryMutationFromUnknown(candidate.result);
  return null;
};

const dispatchProjectHistoryMutationFromUnknown = (value: unknown): boolean => {
  const mutation = projectHistoryMutationFromUnknown(value);
  if (!mutation) return true;
  if (applyServerAuthoritativeProjectMutationResult) {
    return applyServerAuthoritativeProjectMutationResult(mutation);
  }
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent<ProjectHistoryMutationResult>(projectHistoryChangedEvent, { detail: mutation }));
  }
  return true;
};

const markAuthoritativeApplicationCurrent = (value: unknown, current: boolean) => {
  if (!value || typeof value !== "object") return;
  try {
    Object.defineProperty(value, authoritativeApplicationCurrentProperty, {
      configurable: true,
      enumerable: false,
      value: current,
    });
  } catch {
    // Tauri result objects are mutable; a defensive frozen mock still must not
    // prevent the authoritative mutation itself from being applied.
  }
};

const authoritativeApplicationIsCurrent = (value: unknown): boolean => Boolean(
  value
  && typeof value === "object"
  && (value as Record<string, unknown>)[authoritativeApplicationCurrentProperty] === true,
);

const projectMutationCoalesceKey = (command: string, args?: Record<string, unknown>) => {
  if (!/^(set|update|move|fade|refresh)_/.test(command) || !args) {
    return "";
  }
  const targetEntries = Object.entries(args).filter(([key]) =>
    /(id|ids|attribute|field|index|kind|scope|universe|channel|parameter|name)$/i.test(key),
  );
  return targetEntries.length > 0 ? `${command}:${JSON.stringify(Object.fromEntries(targetEntries))}` : "";
};

/**
 * `invoke` is module-scoped so controller helpers can share the typed facade,
 * while owner registration is specific to one mounted App/WebView.  The App
 * installs this bridge before it starts native work and removes only its own
 * bridge on cleanup.  A missing bridge is deliberately a hard error: native
 * calls must never race an unregistered transaction owner.
 */
type ProjectTransactionOwnerRegistrationBarrier = Readonly<{
  identity: symbol;
  awaitRegistration: () => Promise<void>;
}>;

let projectTransactionOwnerRegistrationBarrier: ProjectTransactionOwnerRegistrationBarrier | null = null;

const awaitProjectTransactionOwnerRegistrationBarrier = async (): Promise<void> => {
  const barrier = projectTransactionOwnerRegistrationBarrier;
  if (!barrier) {
    throw new Error("Project transaction owner registration is unavailable; native work was not dispatched.");
  }
  await barrier.awaitRegistration();
};

const invoke = async <T,>(
  command: FrontendTauriInvokeCommand,
  args?: Record<string, unknown>,
): Promise<T> => {
  if (!isTauriRuntime()) {
    throw new Error(tauriBackendUnavailableMessage);
  }
  // This is intentionally outside the transaction branches. Every native
  // generic call (including reads, mapping flushes, Begin and Commit) waits
  // for a concrete window owner; the registration command itself uses the
  // direct Tauri primitive below so it cannot recurse through this facade.
  await awaitProjectTransactionOwnerRegistrationBarrier();
  const rendererTicketedMutation = projectMutationCommands.has(command);
  const serverAuthoritativeMutation = serverAuthoritativeProjectMutationCommands.has(command);
  const projectMutation = rendererTicketedMutation || serverAuthoritativeMutation;
  const terminalRecovery = mediaAssetTerminalRecoveryCommands.has(command)
    || paneWindowTerminalRecoveryCommands.has(command);
  const mediaAssetAvailabilityReadOnly = mediaAssetAvailabilityReadOnlyCommands.has(command);
  if (!terminalRecovery && !mediaAssetAvailabilityReadOnly
    && !operatorCommandAllowed(activeOperatorLockMode, command, projectMutation)) {
    throw new Error(
      activeOperatorLockMode === "Full"
        ? "Operator Full Lock allows only status reads and emergency blackout controls."
        : "Operator Partial Lock blocks programming and project replacement commands.",
    );
  }
  if (projectMutation) {
    await resumeForegroundProjectTransactionTerminalRecoveryBeforeMutation();
  }
  if (!projectMutation) {
    const result = await tauriInvoke<T>(command, args);
    if (command === "get_media_asset_operation_terminal_result") {
      const current = dispatchProjectHistoryMutationFromUnknown(result as MediaAssetAuthoritativeTerminalEnvelope | null);
      markAuthoritativeApplicationCurrent(result, current);
    }
    if (command === "get_video_clip_slot_operation_terminal_result") {
      const current = dispatchProjectHistoryMutationFromUnknown(result);
      markAuthoritativeApplicationCurrent(result, current);
    }
    if (command === "get_video_effect_catalog_operation_terminal_result"
      || command === "get_timeline_advanced_operation_terminal_result") {
      const current = dispatchProjectHistoryMutationFromUnknown(result);
      markAuthoritativeApplicationCurrent(result, current);
    }
    return result;
  }
  const requestedExpectedEpoch = typeof args?.__expectedProjectEpoch === "number"
    ? args.__expectedProjectEpoch
    : null;
  const requestedExpectedRevision = typeof args?.__expectedProjectRevision === "number"
    ? args.__expectedProjectRevision
    : null;
  const requestedExpectedCheckpointHash = typeof args?.__expectedCheckpointHash === "string"
    ? args.__expectedCheckpointHash
    : null;
  const onProjectTransactionOpened = typeof args?.__onProjectTransactionOpened === "function"
    ? args.__onProjectTransactionOpened as () => void
    : null;
  const shouldAbortProjectMutation = typeof args?.__shouldAbortProjectMutation === "function"
    ? args.__shouldAbortProjectMutation as () => boolean
    : null;
  const awaitProjectMutationAbort = typeof args?.__awaitProjectMutationAbort === "function"
    ? args.__awaitProjectMutationAbort as () => Promise<void> | void
    : null;
  // The authored effect vertical captures a complete backend-issued fence
  // after its own mapping barrier. It must not synthesize a renderer epoch,
  // owner ID or generic Begin/Commit ticket around that strict envelope.
  const authoredEffectFencePrepared = command === "set_effect_enabled"
    && args?.__authoredEffectFencePrepared === true;
  // Mapping persistence is itself the barrier that publishes the current
  // mapping generation. Re-entering the generic mapping flush here would
  // recursively dispatch the same command. Its exact CAS epoch/revision are
  // already captured by persistProjectControlMappings below.
  const projectMappingsFencePrepared = command === "set_project_control_mappings";
  const commandArgs = { ...(args ?? {}) };
  delete commandArgs.__expectedProjectEpoch;
  delete commandArgs.__expectedProjectRevision;
  delete commandArgs.__expectedCheckpointHash;
  // Renderer-only lifecycle hooks for staged long-I/O helpers. Never let a
  // closure cross the Tauri boundary. Begin/Commit/Cancel all use the same
  // operation receipt and recovery lane, including transport reply loss.
  delete commandArgs.__onProjectTransactionOpened;
  delete commandArgs.__shouldAbortProjectMutation;
  delete commandArgs.__awaitProjectMutationAbort;
  delete commandArgs.__authoredEffectFencePrepared;
  // Mapping edits are debounced independently of the generic history wrapper.
  // Materialize their authoritative checkpoint before capturing this
  // transaction's `before` image, so a fast fader/edit cannot silently fold an
  // older mapping generation into a later engine mutation.
  // Capture the identity before the async mapping barrier. A replacement
  // during that await must not let this old click reserve a B transaction.
  const currentEpoch = authoredEffectFencePrepared || projectMappingsFencePrepared
    ? requestedExpectedEpoch ?? 0
    : await flushProjectControlMappingsBeforeProjectMutation?.() ?? 0;
  // Dialog-fenced mutations captured the full authority token before their
  // dialog opened. Compare every captured member against the post-flush
  // current authority BEFORE Begin so a project replacement while the dialog
  // was open fails closed with nothing applied.
  if (requestedExpectedEpoch !== null && requestedExpectedEpoch !== currentEpoch) {
    throw new Error("Project changed while the operation dialog was open; nothing was applied.");
  }
  if (requestedExpectedRevision !== null && requestedExpectedRevision !== projectTransactionAuthorityRevision) {
    throw new Error("Project changed while the operation dialog was open; nothing was applied.");
  }
  if (requestedExpectedCheckpointHash !== null && requestedExpectedCheckpointHash !== projectTransactionAuthorityCheckpointHash) {
    throw new Error("Project changed while the operation dialog was open; nothing was applied.");
  }
  const expectedEpoch = requestedExpectedEpoch ?? currentEpoch;
  const expectedRevision = requestedExpectedRevision ?? projectTransactionAuthorityRevision;
  const expectedCheckpointHash = requestedExpectedCheckpointHash
    ?? projectTransactionAuthorityCheckpointHash;
  if (shouldAbortProjectMutation?.()) {
    throw new DOMException("Project mutation was cancelled before dispatch.", "AbortError");
  }
  if (serverAuthoritativeMutation) {
    const strictServerAuthoritativeMutation = command === "create_cue_list"
      || command === "rename_cue_list"
      || command === "reorder_cue_lists"
      || command === "delete_cue_list"
      || command === "create_scene_authoritative_v1";
    const authoritativeCommandArgs = command === "set_effect_enabled"
      ? commandArgs
      : strictServerAuthoritativeMutation
        ? {
          request: {
            ...commandArgs,
            expectedEpoch,
            ownerId: projectTransactionOwnerId,
          },
        }
        : {
          ...commandArgs,
          expectedEpoch,
          ownerId: projectTransactionOwnerId,
        };
    const result = await tauriInvoke<T>(command, authoritativeCommandArgs);
    const current = dispatchProjectHistoryMutationFromUnknown(result);
    markAuthoritativeApplicationCurrent(result, current);
    return result;
  }
  const transactionLabel = projectMutationLabel(command).trim().slice(0, 80);
  const transactionCoalesceKey = projectMutationCoalesceKey(command, args).trim().slice(0, 240);
  const transactionShapeFingerprint = projectTransactionShapeFingerprint(
    command,
    transactionLabel,
    transactionCoalesceKey,
  );
  const clientOperationId = projectTransactionOperationId();
  const transactionIdentity = {
    clientOperationId,
    shapeFingerprint: transactionShapeFingerprint,
    commandName: command,
    schemaVersion: PROJECT_TRANSACTION_SCHEMA_VERSION,
    ownerId: projectTransactionOwnerId,
  };
  const beginArgs = {
    label: transactionLabel,
    coalesceKey: transactionCoalesceKey,
    expectedEpoch,
    expectedRevision,
    expectedCheckpointHash,
    ...transactionIdentity,
  };
  let transaction: ProjectTransactionTicket;
  try {
    transaction = await beginProjectTransactionWithRecovery(beginArgs, transactionIdentity);
  } catch (beginError) {
    throw beginError;
  }
  return executeProjectTransactionMutation<T>({
    command,
    commandArgs,
    transaction,
    identity: transactionIdentity,
    onOpened: onProjectTransactionOpened,
    shouldAbort: shouldAbortProjectMutation,
    awaitAbort: awaitProjectMutationAbort,
  });
};

const listen = <T,>(event: string, handler: (event: { payload: T }) => void) => {
  if (!isTauriRuntime()) {
    return Promise.reject(new Error(tauriBackendUnavailableMessage));
  }
  return tauriListen<T>(event, handler);
};

const isSyndocalProjectPath = (path: string) => path.trim().toLowerCase().endsWith(".sdc");
const timelineAudioFileExtensions = ["wav", "mp3", "m4a", "aac", "flac", "aiff", "aif", "ogg", "opus"];
const visualMediaFileExtensions = ["mp4", "mov", "mxf", "avi", "mkv", "webm", "gif", "png", "jpg", "jpeg", "webp", "bmp", "tif", "tiff"];
const isTimelineAudioFilePath = (path: string) => {
  const normalized = path.trim().toLowerCase();
  return timelineAudioFileExtensions.some((extension) => normalized.endsWith(`.${extension}`));
};
const uiScaleStorageKey = "syndocal.uiScale.v1";
type UiScale = 90 | 100 | 110;
const loadUiScale = (): UiScale => {
  try {
    const value = Number.parseInt(localStorage.getItem(uiScaleStorageKey) ?? "100", 10);
    return value === 90 || value === 110 ? value : 100;
  } catch {
    return 100;
  }
};

const profileLoadMessage = (prefix: string, profile: FixtureProfileSummary) => {
  const warningSuffix =
    profile.warnings.length > 0
      ? ` (${profile.warnings.length} warning${profile.warnings.length === 1 ? "" : "s"})`
      : "";
  return `${prefix} ${profile.manufacturer} ${profile.name}${warningSuffix}`;
};

